def _build_component_06():
    def solve(data):
        packages = data["packages"]
        names = sorted(packages, reverse=True)
        features = set(data.get("features", []))
        blocked = data.get("blocked", {})
        pins = data.get("pins", {})
        roots = data["roots"]
        options = {}
        for name in names:
            options[name] = [row["version"] for row in packages[name]
                             if row["version"] not in blocked.get(name, [])
                             and (name not in pins or row["version"] == pins[name])]

        best_vector = None
        best = None
        assignment = {}

        def check():
            # Root constraints and presence.
            for name, (low, high) in roots.items():
                version = assignment.get(name)
                if version is None or not low <= version <= high:
                    return False

            edges = {name: [] for name in assignment}
            for name, version in assignment.items():
                row = next(r for r in packages[name] if r["version"] == version)
                for dep in row.get("deps", []):
                    feature = dep.get("feature", "")
                    if feature and feature not in features:
                        continue
                    target = dep["name"]
                    chosen_version = assignment.get(target)
                    if chosen_version is None or not dep["min"] <= chosen_version <= dep["max"]:
                        return False
                    edges[name].append(target)

            # Reject cycles, including self loops.
            active, done = set(), set()

            def visit(name):
                if name in active:
                    return False
                if name in done:
                    return True
                active.add(name)
                for target in edges[name]:
                    if not visit(target):
                        return False
                active.remove(name)
                done.add(name)
                return True

            if not all(visit(name) for name in edges):
                return False

            # Installed packages must be exactly the roots' dependency closure.
            reachable = set()
            stack = list(roots)
            while stack:
                name = stack.pop()
                if name in reachable:
                    continue
                reachable.add(name)
                stack.extend(edges[name])
            return reachable == set(assignment)

        def search(i):
            nonlocal best_vector, best
            if i == len(names):
                if check():
                    vector = tuple(assignment.get(name, -1) for name in names)
                    if best_vector is None or vector > best_vector:
                        best_vector = vector
                        best = dict(assignment)
                return
            name = names[i]
            assignment.pop(name, None)
            search(i + 1)
            for version in options[name]:
                assignment[name] = version
                search(i + 1)
            assignment.pop(name, None)

        search(0)
        if best is None:
            return {"error": "unsatisfiable"}
        return {"versions": best}

    return solve


def _build_component_07():
    def solve(data):
        jobs = data["jobs"]
        k = data["k"]
        blocked = set(data.get("blocked", []))
        mandatory = set(data.get("mandatory", []))
        quotas = data.get("quotas", {})
        available = [job for job in jobs if job["id"] not in blocked]
        best_value = None
        best_ids = None

        from itertools import combinations

        for subset in combinations(available, k):
            ids = {job["id"] for job in subset}
            if not mandatory.issubset(ids):
                continue
            counts = {}
            for job in subset:
                counts[job["group"]] = counts.get(job["group"], 0) + 1
            if any(not low <= counts.get(group, 0) <= high
                   for group, (low, high) in quotas.items()):
                continue

            # Half-open intervals: intervals ending at t do not overlap ones starting at t.
            times = sorted({t for job in subset for t in (job["start"], job["end"])})
            if any(sum(job["start"] <= t < job["end"] for job in subset) > 2
                   for t in times):
                continue

            value = sum(job["value"] for job in subset)
            selected_ids = tuple(sorted(ids))
            if (best_value is None or value > best_value or
                    (value == best_value and selected_ids > best_ids)):
                best_value, best_ids = value, selected_ids

        if best_value is None:
            return {"error": "impossible"}
        return {"selected": list(best_ids), "value": best_value}

    return solve


def _build_component_08():
    import heapq

    def solve(data):
        required = data.get("required", [])
        bit_for = {node: 1 << i for i, node in enumerate(required)}
        full = (1 << len(required)) - 1
        graph = [[] for _ in range(data["n"])]
        for edge in data["edges"]:
            graph[edge["u"]].append(edge)

        source = data["source"]
        initial_mask = bit_for.get(source, 0)
        start_state = (source, initial_mask, data["coupons"])
        distances = {start_state: data["start"]}
        queue = [(data["start"], source, initial_mask, data["coupons"])]

        while queue:
            arrival, node, mask, coupons = heapq.heappop(queue)
            state = (node, mask, coupons)
            if distances.get(state) != arrival:
                continue
            if node == data["target"] and mask == full:
                return {"arrival": arrival}

            for edge in graph[node]:
                depart = max(arrival, edge["open"])
                if depart >= edge["close"]:
                    continue
                choices = [(edge["duration"], coupons)]
                if coupons:
                    duration = max(1, edge["duration"] - edge.get("discount", 0))
                    choices.append((duration, coupons - 1))
                next_node = edge["v"]
                next_mask = mask | bit_for.get(next_node, 0)
                for duration, remaining in choices:
                    next_time = depart + duration
                    if next_time > data["deadline"]:
                        continue
                    next_state = (next_node, next_mask, remaining)
                    if next_time < distances.get(next_state, float("inf")):
                        distances[next_state] = next_time
                        heapq.heappush(queue, (next_time, next_node, next_mask, remaining))

        return {"arrival": None}

    return solve


